css:
.cmp-surv-queue{box-sizing:border-box;width:100%;max-width:380px;padding:10px 11px 9px;border-radius:12px;background:linear-gradient(180deg,#141926 0%,#0B0E15 100%);border:1px solid rgba(255,255,255,.08);color:#E6EBF5;font-family:system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;}
.cmp-surv-queue *{box-sizing:border-box;}
.cmp-surv-queue-hd{display:flex;align-items:center;justify-content:space-between;gap:8px;}
.cmp-surv-queue-ttl{font-size:11px;font-weight:650;letter-spacing:.02em;}
.cmp-surv-queue-clk{font-family:ui-monospace,Menlo,Consolas,monospace;font-size:9.5px;color:#7C879E;font-variant-numeric:tabular-nums;}
.cmp-surv-queue-sev{display:flex;align-items:center;gap:5px;margin:7px 0 6px;}
.cmp-surv-queue-chip{display:inline-flex;gap:4px;align-items:center;padding:2px 6px;border-radius:5px;font-size:8.5px;font-weight:700;letter-spacing:.08em;border:1px solid transparent;font-variant-numeric:tabular-nums;}
.cmp-surv-queue-chip b{font-weight:700;}
.cmp-surv-queue-h{color:#FF6B78;background:rgba(255,107,120,.10);border-color:rgba(255,107,120,.28);}
.cmp-surv-queue-m{color:#F5A524;background:rgba(245,165,36,.10);border-color:rgba(245,165,36,.26);}
.cmp-surv-queue-l{color:#7C879E;background:rgba(255,255,255,.04);border-color:rgba(255,255,255,.10);}
.cmp-surv-queue-open{margin-left:auto;font-size:9px;color:#7C879E;letter-spacing:.04em;}
.cmp-surv-queue-open b{color:#E6EBF5;font-variant-numeric:tabular-nums;}
.cmp-surv-queue-cols,.cmp-surv-queue-row{display:grid;grid-template-columns:50px minmax(0,1fr) 40px 18px 24px;gap:3px;align-items:center;}
.cmp-surv-queue-cols{padding:0 3px 3px;font-size:8px;letter-spacing:.1em;color:#5E6880;border-bottom:1px solid rgba(255,255,255,.07);}
.cmp-surv-queue-cols span:nth-child(4),.cmp-surv-queue-cols span:nth-child(5){text-align:right;}
.cmp-surv-queue-list{position:relative;max-height:136px;overflow-y:auto;outline:none;scrollbar-width:thin;}
.cmp-surv-queue-list::-webkit-scrollbar{width:5px;}
.cmp-surv-queue-list::-webkit-scrollbar-thumb{background:rgba(255,255,255,.13);border-radius:3px;}
.cmp-surv-queue-list:focus-visible{box-shadow:inset 0 0 0 1px rgba(91,156,248,.55);border-radius:6px;}
.cmp-surv-queue-row{position:relative;padding:4px 3px;border-bottom:1px solid rgba(255,255,255,.045);font-family:ui-monospace,Menlo,Consolas,monospace;font-size:9.5px;cursor:pointer;font-variant-numeric:tabular-nums;}
.cmp-surv-queue-row::before{content:"";position:absolute;left:0;top:3px;bottom:3px;width:2px;border-radius:2px;background:#5E6880;}
.cmp-surv-queue-row[data-sev="H"]::before{background:#FF6B78;}
.cmp-surv-queue-row[data-sev="M"]::before{background:#F5A524;}
.cmp-surv-queue-row:hover{background:rgba(255,255,255,.035);}
.cmp-surv-queue-row.cmp-surv-queue-sel{background:rgba(91,156,248,.14);}
.cmp-surv-queue-row[data-state]{opacity:.42;}
.cmp-surv-queue-id{color:#9FB0CC;display:flex;align-items:center;gap:3px;font-size:9px;white-space:nowrap;}
.cmp-surv-queue-tag{font-style:normal;font-size:7.5px;letter-spacing:.06em;padding:0 3px;border-radius:3px;background:rgba(255,255,255,.10);color:#C9D4E8;}
.cmp-surv-queue-tag:empty{display:none;}
.cmp-surv-queue-scn{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#E6EBF5;font-family:system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;font-size:10px;}
.cmp-surv-queue-sym{color:#8FA3C4;overflow:hidden;text-overflow:ellipsis;}
.cmp-surv-queue-scr{text-align:right;font-weight:700;color:#5E6880;}
.cmp-surv-queue-row[data-sev="H"] .cmp-surv-queue-scr{color:#FF6B78;}
.cmp-surv-queue-row[data-sev="M"] .cmp-surv-queue-scr{color:#F5A524;}
.cmp-surv-queue-age{text-align:right;color:#5E6880;}
.cmp-surv-queue-det{margin-top:7px;padding:6px 7px;border-radius:7px;background:rgba(255,255,255,.035);border:1px solid rgba(255,255,255,.06);font-size:9.5px;line-height:1.42;color:#9FB0CC;min-height:44px;}
.cmp-surv-queue-det b{color:#E6EBF5;font-weight:650;}
.cmp-surv-queue-det em{font-style:normal;color:#7C879E;font-family:ui-monospace,Menlo,Consolas,monospace;}
.cmp-surv-queue-det.cmp-surv-queue-flash{animation:cmp-surv-queue-flash .5s ease-out;}
.cmp-surv-queue-det.cmp-surv-queue-esc{border-color:rgba(255,107,120,.35);color:#FFC2C7;}
.cmp-surv-queue-det.cmp-surv-queue-clr{border-color:rgba(47,212,138,.30);color:#9BE7C4;}
.cmp-surv-queue-keys{display:flex;gap:9px;margin-top:6px;font-size:8px;letter-spacing:.06em;color:#4F586E;text-transform:uppercase;}
@keyframes cmp-surv-queue-flash{0%{background:rgba(91,156,248,.22);}100%{background:rgba(255,255,255,.035);}}
@media (prefers-reduced-motion: reduce){
.cmp-surv-queue-det.cmp-surv-queue-flash{animation:none;}
}

js:
var list = root.querySelector('.cmp-surv-queue-list');
var rows = Array.prototype.slice.call(root.querySelectorAll('.cmp-surv-queue-row'));
var det  = root.querySelector('.cmp-surv-queue-det');
var clk  = root.querySelector('.cmp-surv-queue-clk');
var nh   = root.querySelector('.cmp-surv-queue-nh');
var nm   = root.querySelector('.cmp-surv-queue-nm');
var nl   = root.querySelector('.cmp-surv-queue-nl');
var no   = root.querySelector('.cmp-surv-queue-no');
var idx = 0, secs = 9 * 3600 + 41 * 60 + 22, caseNo = 1147;

function pad(n){ return (n < 10 ? '0' : '') + n; }
function age(m){ return m < 60 ? m + 'm' : (Math.floor(m / 60) + 'h' + pad(m % 60)); }

function counts(){
  var c = { H:0, M:0, L:0 }, open = 0;
  rows.forEach(function(r){
    if (!r.getAttribute('data-state')) { open++; c[r.getAttribute('data-sev')]++; }
  });
  nh.textContent = c.H; nm.textContent = c.M; nl.textContent = c.L; no.textContent = open;
}

function show(){
  var r = rows[idx];
  det.className = 'cmp-surv-queue-det';
  det.innerHTML = '<b>' + r.querySelector('.cmp-surv-queue-id').firstChild.nodeValue + '</b> &middot; <em>' +
                  r.getAttribute('data-trd') + '</em><br>' + r.getAttribute('data-det');
}

function select(n){
  idx = Math.max(0, Math.min(rows.length - 1, n));
  rows.forEach(function(r, i){
    r.classList.toggle('cmp-surv-queue-sel', i === idx);
    r.setAttribute('aria-selected', i === idx ? 'true' : 'false');
  });
  var r = rows[idx];
  if (r.offsetTop < list.scrollTop) list.scrollTop = r.offsetTop;
  else if (r.offsetTop + r.offsetHeight > list.scrollTop + list.clientHeight)
    list.scrollTop = r.offsetTop + r.offsetHeight - list.clientHeight;
  show();
}

function action(kind){
  var r = rows[idx];
  if (r.getAttribute('data-state')) return;
  r.setAttribute('data-state', kind);
  r.querySelector('.cmp-surv-queue-tag').textContent = kind;
  var aid = r.querySelector('.cmp-surv-queue-id').firstChild.nodeValue;
  det.className = 'cmp-surv-queue-det cmp-surv-queue-flash ' +
                  (kind === 'ESC' ? 'cmp-surv-queue-esc' : 'cmp-surv-queue-clr');
  det.innerHTML = kind === 'ESC'
    ? '<b>' + aid + '</b> escalated to L2 review &middot; case <em>CS-2026-' + (caseNo++) +
      '</em> opened, trader comms preserved, 4-eyes sign-off required'
    : '<b>' + aid + '</b> closed no-action &middot; rationale <em>benign / client-driven</em> logged to the audit trail, retained 5y';
  counts();
  for (var i = idx + 1; i < rows.length; i++) {
    if (!rows[i].getAttribute('data-state')) { setTimeout(function(j){ return function(){ select(j); }; }(i), 900); break; }
  }
}

rows.forEach(function(r, i){ r.addEventListener('click', function(){ select(i); list.focus(); }); });
list.addEventListener('keydown', function(e){
  var k = e.key;
  if (k === 'ArrowDown') { e.preventDefault(); select(idx + 1); }
  else if (k === 'ArrowUp') { e.preventDefault(); select(idx - 1); }
  else if (k === 'Enter') { e.preventDefault(); action('ESC'); }
  else if (k === 'x' || k === 'X') { e.preventDefault(); action('CLR'); }
});

var tick = setInterval(function(){
  if (!root.isConnected) { clearInterval(tick); return; }
  secs++;
  clk.textContent = pad(Math.floor(secs / 3600)) + ':' + pad(Math.floor(secs / 60) % 60) + ':' + pad(secs % 60) + 'Z';
  if (secs % 60 === 0) rows.forEach(function(r){
    var m = +r.getAttribute('data-min') + 1;
    r.setAttribute('data-min', m);
    r.querySelector('.cmp-surv-queue-age').textContent = age(m);
  });
}, 1000);

counts();
select(0);

