js:
var inp   = root.querySelector('.cmp-restricted-list-inp');
var clr   = root.querySelector('.cmp-restricted-list-clr');
var rows  = Array.prototype.slice.call(root.querySelectorAll('.cmp-restricted-list-row'));
var none  = root.querySelector('.cmp-restricted-list-none');
var n     = root.querySelector('.cmp-restricted-list-n');
var fbtns = Array.prototype.slice.call(root.querySelectorAll('.cmp-restricted-list-f'));
var kind = 'all';

function apply(){
  var q = inp.value.trim().toLowerCase(), shown = 0;
  rows.forEach(function(r){
    var ok = (kind === 'all' || r.getAttribute('data-k') === kind) &&
             (!q || r.getAttribute('data-s').indexOf(q) > -1);
    r.classList.toggle('cmp-restricted-list-hide', !ok);
    if (ok) shown++;
  });
  n.textContent = shown;
  none.classList.toggle('cmp-restricted-list-vis', shown === 0);
  clr.classList.toggle('cmp-restricted-list-vis', inp.value.length > 0);
  if (shown === 1 && q) {
    var hit = rows.filter(function(r){ return !r.classList.contains('cmp-restricted-list-hide'); })[0];
    hit.classList.remove('cmp-restricted-list-newhit');
    void hit.offsetWidth;
    hit.classList.add('cmp-restricted-list-newhit');
  }
}

inp.addEventListener('input', apply);
inp.addEventListener('keydown', function(e){
  if (e.key === 'Escape') { inp.value = ''; apply(); }
});
clr.addEventListener('click', function(){ inp.value = ''; inp.focus(); apply(); });
fbtns.forEach(function(b){
  b.addEventListener('click', function(){
    kind = b.getAttribute('data-f');
    fbtns.forEach(function(x){
      var on = x === b;
      x.classList.toggle('cmp-restricted-list-on', on);
      x.setAttribute('aria-pressed', on ? 'true' : 'false');
    });
    apply();
  });
});
apply();

css:
.cmp-pad-request{box-sizing:border-box;width:100%;max-width:380px;padding:10px 11px 9px;border-radius:12px;background:linear-gradient(180deg,#141926 0%,#0B0E15 100%);border:1px solid rgba(255,255,255,.08);color:#E6EBF5;font-family:system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;}
.cmp-pad-request *{box-sizing:border-box;}
.cmp-pad-request-hd{display:flex;align-items:center;justify-content:space-between;gap:8px;}
.cmp-pad-request-ttl{font-size:11px;font-weight:650;}
.cmp-pad-request-ref{font-family:ui-monospace,Menlo,Consolas,monospace;font-size:9px;color:#5E6880;}
.cmp-pad-request-who{margin:3px 0 7px;font-size:8.5px;letter-spacing:.05em;color:#5E6880;text-transform:uppercase;}
.cmp-pad-request-who b{color:#9FB0CC;font-variant-numeric:tabular-nums;font-weight:600;}
