.cmp-pad-request-calc{display:flex;justify-content:space-between;gap:8px;margin:6px 0 7px;padding:5px 7px;border-radius:7px;background:rgba(255,255,255,.035);font-family:ui-monospace,Menlo,Consolas,monospace;font-size:9px;color:#5E6880;letter-spacing:.04em;font-variant-numeric:tabular-nums;}
