.cmp-pad-request-mark{font-size:10px;line-height:1.3;color:#4F586E;text-align:center;}
.cmp-pad-request-chk[data-s="ok"] .cmp-pad-request-mark{color:#2FD48A;}
.cmp-pad-request-chk[data-s="fail"] .cmp-pad-request-mark{color:#FF6B78;}
