.cmp-pad-request-chk[data-s="fail"] .cmp-pad-request-cmsg{color:#FF8A94;}
.cmp-pad-request-sub{width:100%;margin-top:8px;padding:6px 0;border-radius:7px;border:1px solid rgba(91,156,248,.40);background:rgba(91,156,248,.14);color:#BBD4FF;font-family:inherit;font-size:9px;font-weight:700;letter-spacing:.10em;cursor:pointer;transition:background .15s ease,color .15s ease;}
.cmp-pad-request-sub:hover{background:rgba(91,156,248,.24);color:#EAF2FF;}
.cmp-pad-request-sub:focus-visible{outline:2px solid #5B9CF8;outline-offset:2px;}
.cmp-pad-request-out{margin-top:6px;padding:0;font-family:ui-monospace,Menlo,Consolas,monospace;font-size:9px;line-height:1.45;border-radius:7px;overflow:hidden;max-height:0;transition:max-height .2s ease;}
.cmp-pad-request-out.cmp-pad-request-shown{max-height:70px;padding:6px 8px;border:1px solid transparent;}
.cmp-pad-request-out.cmp-pad-request-ok{border-color:rgba(47,212,138,.35);background:rgba(47,212,138,.09);color:#9BE7C4;}
