.cmp-pad-request-out b{display:block;font-size:9.5px;letter-spacing:.10em;margin-bottom:2px;}
.cmp-pad-request-out.cmp-pad-request-ok b{color:#2FD48A;}
.cmp-pad-request-out.cmp-pad-request-no b{color:#FF6B78;}
@media (prefers-reduced-motion: reduce){
.cmp-pad-request-out{transition:none;}
.cmp-pad-request-sub{transition:none;}
}

js:
var sym  = root.querySelector('.cmp-pad-request-sym');
var qty  = root.querySelector('.cmp-pad-request-qty');
var pxEl = root.querySelector('.cmp-pad-request-px');
var nvEl = root.querySelector('.cmp-pad-request-nv');
var out  = root.querySelector('.cmp-pad-request-out');
var sub  = root.querySelector('.cmp-pad-request-sub');
var sbs  = Array.prototype.slice.call(root.querySelectorAll('.cmp-pad-request-sb'));
var chk  = {};
Array.prototype.slice.call(root.querySelectorAll('.cmp-pad-request-chk')).forEach(function(li){
  chk[li.getAttribute('data-c')] = li;
});

var BOOK = {
  AAPL:{px:232.15, held:0},   MSFT:{px:421.60, held:0},   NVDA:{px:178.40, held:0},
  SAP:{px:214.80,  held:0},   TSM:{px:189.25,  held:14},  VOD:{px:8.94,    held:0},
  BARC:{px:12.40,  held:0},   RIO:{px:68.20,   held:0},   ASML:{px:742.10, held:0},
  SIE:{px:198.35,  held:0},   ENI:{px:16.02,   held:212}, INFY:{px:19.85, held:0}
};
var RESTRICTED = { NVDA:'M&A advisory', SIE:'MNPI held', RIO:'M&A advisory', INFY:'MNPI held' };
var FIRM_ORDER = { VOD:'240k parent working', BARC:'client block in market', ASML:'IOI live 09:30' };
var side = 'BUY', used = 14, CAP = 50000, seq = 418;

function money(v){
  return v.toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g, ',');
}
function set(k, ok, msg){
  chk[k].setAttribute('data-s', ok ? 'ok' : 'fail');
  chk[k].querySelector('.cmp-pad-request-mark').textContent = ok ? '✓' : '✕';
  chk[k].querySelector('.cmp-pad-request-cmsg').textContent = msg;
  return ok;
}

function evaluate(){
  var t = sym.value.trim().toUpperCase();
  var q = parseInt(qty.value.replace(/[^0-9]/g, ''), 10) || 0;
  var row = BOOK[t];
  var px = row ? row.px : 0;
  var nv = px * q;
  pxEl.textContent = row ? px.toFixed(2) : '--.--';
  nvEl.textContent = 'USD ' + (row ? money(nv) : '0.00');

  var pass = [];
  if (!row) pass.push(set('rl', false, 'unknown symbol'));
  else if (RESTRICTED[t]) pass.push(set('rl', false, RESTRICTED[t]));
  else pass.push(set('rl', true, 'not listed'));

  pass.push(FIRM_ORDER[t] ? set('fo', false, FIRM_ORDER[t]) : set('fo', true, 'no firm interest'));

  if (side !== 'SELL') pass.push(set('hp', true, 'n/a on buy'));
  else if (!row) pass.push(set('hp', false, 'unknown symbol'));
  else if (row.held === 0) pass.push(set('hp', false, 'no position on file'));
  else if (row.held < 30) pass.push(set('hp', false, 'opened ' + row.held + 'd ago'));
  else pass.push(set('hp', true, row.held + 'd held'));

  pass.push(set('cnt', used < 20, used + ' of 20 used'));
  pass.push(set('not', q > 0 && nv <= CAP, q > 0 ? money(nv) + ' / 50,000' : 'qty required'));

  var bad = pass.filter(function(x){ return !x; }).length;
  sub.textContent = bad ? 'SUBMIT — ' + bad + ' RULE' + (bad > 1 ? 'S' : '') + ' FAILING'
                        : 'SUBMIT FOR PRE-CLEARANCE';
  return bad;
}

function submit(){
  var bad = evaluate();
  var t = sym.value.trim().toUpperCase();
  out.className = 'cmp-pad-request-out cmp-pad-request-shown ' +
                  (bad ? 'cmp-pad-request-no' : 'cmp-pad-request-ok');
  if (bad) {
    var first = Array.prototype.slice.call(root.querySelectorAll('.cmp-pad-request-chk'))
      .filter(function(li){ return li.getAttribute('data-s') === 'fail'; })[0];
    out.innerHTML = '<b>BLOCKED</b>' + first.querySelector('.cmp-pad-request-clab').textContent +
      ' — ' + first.querySelector('.cmp-pad-request-cmsg').textContent +
      '<br>request logged, compliance notified, no OMS entitlement issued';
  } else {
    used++;
    root.querySelector('.cmp-pad-request-who b').textContent = used + '/20';
    out.innerHTML = '<b>APPROVED</b>ref PAD-2026-0' + (++seq) + ' · ' + side + ' ' +
      qty.value + ' ' + t + '<br>valid 24h to 10:41Z tomorrow · 30d holding lock applies';
    evaluate();
  }
}

sym.addEventListener('input', function(){
  sym.value = sym.value.toUpperCase();
  out.className = 'cmp-pad-request-out';
  evaluate();
});
qty.addEventListener('input', function(){ out.className = 'cmp-pad-request-out'; evaluate(); });
sbs.forEach(function(b){
  b.addEventListener('click', function(){
    side = b.getAttribute('data-side');
    sbs.forEach(function(x){
      var on = x === b;
      x.classList.toggle('cmp-pad-request-on', on);
      x.setAttribute('aria-pressed', on ? 'true' : 'false');
    });
    out.className = 'cmp-pad-request-out';
    evaluate();
  });
});
sub.addEventListener('click', submit);
evaluate();

