var PX = 214.80, PRE_SH = 38175, NAV = 520;
var LIM = { name:15.00, sector:60.00, book:750.00, delta:120.00, conc:3.10, liq:5.00 };
var rows = Array.prototype.slice.call(root.querySelectorAll('.cmp-limit-breach-row'));
var btns = Array.prototype.slice.call(root.querySelectorAll('.cmp-limit-breach-sz'));
var maxb = root.querySelector('.cmp-limit-breach-max');
var verd = root.querySelector('.cmp-limit-breach-verdict');
var vlab = root.querySelector('.cmp-limit-breach-vlab');
var vtxt = root.querySelector('.cmp-limit-breach-vtxt');
var qEl  = root.querySelector('.cmp-limit-breach-qty');
var nEl  = root.querySelector('.cmp-limit-breach-not');

function value(k, q){
  var inc = q * PX / 1e6;
  if (k === 'name')   return (PRE_SH + q) * PX / 1e6;
  if (k === 'sector') return 41.31 + inc;
  if (k === 'book')   return 612.40 + inc;
  if (k === 'delta')  return 96.20 + inc;
  if (k === 'conc')   return (PRE_SH + q) * PX / 1e6 / NAV * 100;
  return (PRE_SH + q) / 27500;
}
function state(u){ return u >= 100 ? 'breach' : (u >= 85 ? 'warn' : 'ok'); }
function grp(n){ return n.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ','); }

function render(q){
  var breaches = 0, warns = 0;
  rows.forEach(function(r){
    var k = r.getAttribute('data-k'), lim = LIM[k];
    var pre = value(k, 0), post = value(k, q);
    var up = pre / lim * 100, uq = post / lim * 100, st = state(uq);
    if (st === 'breach') breaches++; else if (st === 'warn') warns++;
    r.setAttribute('data-s', st);
    r.querySelector('.cmp-limit-breach-pre').textContent = pre.toFixed(2);
    r.querySelector('.cmp-limit-breach-post').textContent = post.toFixed(2);
    r.querySelector('.cmp-limit-breach-bpost').style.width = Math.min(uq, 100).toFixed(1) + '%';
    r.querySelector('.cmp-limit-breach-bpre').style.width = Math.min(up, 100).toFixed(1) + '%';
    r.querySelector('.cmp-limit-breach-pill').textContent = uq.toFixed(1) + '% ' + st.toUpperCase();
  });
  qEl.textContent = grp(q);
  nEl.innerHTML = '&euro;' + (q * PX / 1e6).toFixed(2) + 'mm';
  if (breaches) {
    verd.setAttribute('data-s', 'breach');
    vlab.textContent = 'REJECT';
    vtxt.innerHTML = breaches + ' hard breach' + (breaches > 1 ? 'es' : '') +
                     ' &middot; override requires 2 approvers';
  } else if (warns) {
    verd.setAttribute('data-s', 'warn');
    vlab.textContent = 'PASS';
    vtxt.innerHTML = warns + ' limit' + (warns > 1 ? 's' : '') +
                     ' above 85% &middot; desk head notified on fill';
  } else {
    verd.setAttribute('data-s', 'ok');
    vlab.textContent = 'PASS';
    vtxt.innerHTML = 'all 6 limits within tolerance &middot; released to OMS';
  }
}

function pick(b, q){
  btns.forEach(function(x){ x.classList.toggle('cmp-limit-breach-on', x === b); });
  render(q);
}
btns.forEach(function(b){
  b.addEventListener('click', function(){ pick(b, +b.getAttribute('data-q')); });
});
maxb.addEventListener('click', function(){ pick(null, +maxb.getAttribute('data-q')); });
render(40000);

