var items = Array.prototype.slice.call(root.querySelectorAll('.cmp-audit-trail-item'));
var tabs  = Array.prototype.slice.call(root.querySelectorAll('.cmp-audit-trail-tab'));
var n     = root.querySelector('.cmp-audit-trail-n');

items.forEach(function(it){
  var btn = it.querySelector('.cmp-audit-trail-row');
  btn.addEventListener('click', function(){
    var open = it.classList.contains('cmp-audit-trail-open');
    items.forEach(function(o){
      o.classList.remove('cmp-audit-trail-open');
      o.querySelector('.cmp-audit-trail-row').setAttribute('aria-expanded', 'false');
    });
    if (!open) { it.classList.add('cmp-audit-trail-open'); btn.setAttribute('aria-expanded', 'true'); }
  });
});

tabs.forEach(function(t){
  t.addEventListener('click', function(){
    var g = t.getAttribute('data-g'), shown = 0;
    tabs.forEach(function(x){
      var on = x === t;
      x.classList.toggle('cmp-audit-trail-on', on);
      x.setAttribute('aria-pressed', on ? 'true' : 'false');
    });
    items.forEach(function(it){
      var ok = g === 'ALL' || it.getAttribute('data-g') === g;
      it.classList.toggle('cmp-audit-trail-hide', !ok);
      if (ok) shown++;
    });
    n.textContent = shown;
  });
});

