js:
var EXEC = 71.35;
var tabs = Array.prototype.slice.call(root.querySelectorAll('.cmp-bestex-report-tab'));
var bps  = root.querySelector('.cmp-bestex-report-bps');
var bpx  = root.querySelector('.cmp-bestex-report-bpx');
var word = root.querySelector('.cmp-bestex-report-word');
var mark = root.querySelector('.cmp-bestex-report-mark');

function show(t){
  var px = parseFloat(t.getAttribute('data-px'));
  var b = (EXEC - px) / px * 10000;
  var pos = b >= 0;
  bps.textContent = (pos ? '+' : '−') + Math.abs(b).toFixed(1);
  bps.setAttribute('data-s', pos ? 'pos' : 'neg');
  bpx.textContent = px.toFixed(2) + 'p';
  word.textContent = pos ? 'price improvement' : 'slippage';
  word.setAttribute('data-s', pos ? 'pos' : 'neg');
  mark.style.left = Math.max(2, Math.min(98, (b + 25) / 50 * 100)).toFixed(1) + '%';
  tabs.forEach(function(x){
    var on = x === t;
    x.classList.toggle('cmp-bestex-report-on', on);
    x.setAttribute('aria-pressed', on ? 'true' : 'false');
  });
}

tabs.forEach(function(t){ t.addEventListener('click', function(){ show(t); }); });
show(tabs[0]);

