js:
var items = Array.prototype.slice.call(root.querySelectorAll('.cmp-attest-check-item'));
var segs  = Array.prototype.slice.call(root.querySelectorAll('.cmp-attest-check-seg'));
var done  = root.querySelector('.cmp-attest-check-done');
var sign  = root.querySelector('.cmp-attest-check-sign');
var signed = false;

function refresh(){
  var n = 0;
  items.forEach(function(it, i){
    var on = it.hasAttribute('data-on');
    if (on) n++;
    if (on) segs[i].setAttribute('data-on', '1'); else segs[i].removeAttribute('data-on');
  });
  done.textContent = n;
  if (signed) return;
  var left = items.length - n;
  sign.disabled = left > 0;
  sign.classList.toggle('cmp-attest-check-ready', left === 0);
  sign.textContent = left ? left + ' OUTSTANDING' : 'SIGN & SUBMIT ATTESTATION';
}

items.forEach(function(it){
  it.addEventListener('click', function(){
    if (signed) return;
    var on = it.hasAttribute('data-on');
    if (on) it.removeAttribute('data-on'); else it.setAttribute('data-on', '1');
    it.setAttribute('aria-checked', on ? 'false' : 'true');
    refresh();
  });
});

sign.addEventListener('click', function(){
  if (sign.disabled || signed) return;
  signed = true;
  sign.classList.remove('cmp-attest-check-ready');
  sign.classList.add('cmp-attest-check-done');
  sign.disabled = true;
  sign.textContent = '✓ ATTESTED 09:47:12Z · e-sig 7F3C-91AE';
  root.classList.add('cmp-attest-check-signed');
  root.querySelector('.cmp-attest-check-due').textContent = 'FILED 6D EARLY';
});

refresh();

