js:
var ITEMS = [
  { ch:'BBG IB', ppl:'K.MERCER ↔ EXT/D.SHAW · VELA CAP', risk:87, s:'hi',
    lex:['not in writing','off the record','make you whole'],
    lines:[
      ['09:12','K.MERCER',0,'can you work 250k RIO for me but <mark class="cmp-comms-review-hit">don\'t put this in writing</mark>'],
      ['09:12','D.SHAW',1,'understood — happy to keep it <mark class="cmp-comms-review-hit">off the record</mark>'],
      ['09:13','K.MERCER',0,'if it prints below 68.20 I\'ll <mark class="cmp-comms-review-hit">make you whole</mark> on the difference']
    ]},
  { ch:'SYMPHONY', ppl:'T.NAKAMURA ↔ J.OSEI · PROG DESK', risk:74, s:'md',
    lex:['push it up','nobody will notice'],
    lines:[
      ['08:47','T.NAKAMURA',0,'client wants the close on 7203 — we can <mark class="cmp-comms-review-hit">push it up</mark> in the auction'],
      ['08:48','J.OSEI',0,'how much do we need on the bid'],
      ['08:48','T.NAKAMURA',0,'40k does it, <mark class="cmp-comms-review-hit">nobody will notice</mark> in that volume']
    ]},
  { ch:'EMAIL', ppl:'R.OKONKWO → EXT/P.LOWE · ARDEN AM', risk:91, s:'hi',
    lex:['pre-publication','embargoed','trade around'],
    lines:[
      ['14:22','R.OKONKWO',0,'draft note attached <mark class="cmp-comms-review-hit">pre-publication</mark> — <mark class="cmp-comms-review-hit">strictly embargoed</mark> to Thu 07:00'],
      ['14:31','P.LOWE',1,'useful, we will <mark class="cmp-comms-review-hit">trade around it</mark> before the print goes out']
    ]}
];

var chEl  = root.querySelector('.cmp-comms-review-ch');
var pplEl = root.querySelector('.cmp-comms-review-ppl');
var riskEl= root.querySelector('.cmp-comms-review-risk');
var lexEl = root.querySelector('.cmp-comms-review-lex');
var body  = root.querySelector('.cmp-comms-review-body');
var iEl   = root.querySelector('.cmp-comms-review-i');
var doneEl= root.querySelector('.cmp-comms-review-done');
var barEl = root.querySelector('.cmp-comms-review-bar i');
var logEl = root.querySelector('.cmp-comms-review-log');
var acts  = Array.prototype.slice.call(root.querySelectorAll('.cmp-comms-review-a'));
var cur = 0, item = 3, reviewed = 2, TOTAL = 18;

function render(){
  var d = ITEMS[cur];
  chEl.textContent = d.ch;
  pplEl.textContent = d.ppl;
  riskEl.textContent = d.risk;
  riskEl.setAttribute('data-s', d.s);
  lexEl.innerHTML = d.lex.map(function(t){
    return '<span class="cmp-comms-review-tag">&ldquo;' + t + '&rdquo;</span>';
  }).join('');
  body.innerHTML = d.lines.map(function(l){
    return '<div class="cmp-comms-review-ln' + (l[2] ? ' cmp-comms-review-ext' : '') + '">' +
           '<span class="cmp-comms-review-tm">' + l[0] + '</span>' +
           '<span class="cmp-comms-review-tx"><span class="cmp-comms-review-sp">' + l[1] +
           (l[2] ? ' [EXT]' : '') + '</span> ' + l[3] + '</span></div>';
  }).join('');
  body.classList.remove('cmp-comms-review-swap');
  void body.offsetWidth;
  body.classList.add('cmp-comms-review-swap');
  iEl.textContent = item;
}

function disposition(d){
  logEl.textContent = 'item ' + item + ' ' + d.toLowerCase() + ' · logged 09:47:31Z · j.okafor';
  logEl.setAttribute('data-s', 'done');
  reviewed++;
  doneEl.textContent = reviewed;
  barEl.style.width = (reviewed / TOTAL * 100).toFixed(1) + '%';
  item = item < TOTAL ? item + 1 : TOTAL;
  cur = (cur + 1) % ITEMS.length;
  render();
}

acts.forEach(function(b){
  b.addEventListener('click', function(){ disposition(b.getAttribute('data-d')); });
});
body.addEventListener('keydown', function(e){
  var k = e.key.toLowerCase();
  var map = { '1':'CLEAR', c:'CLEAR', '2':'ESCALATE', e:'ESCALATE', '3':'CONTEXT', r:'CONTEXT' };
  if (map[k]) { e.preventDefault(); disposition(map[k]); }
});
render();
